// ── Full Legislator Profile Interface (per LEGISLATOR_PROFILE_TEMPLATE.md) ──

export interface ElectionRecord {
  electionYear: number;
  electionType: 'assembly' | 'lok_sabha' | 'rajya_sabha' | 'by_election';
  electionKey: string;
  stateCode: string;
  constituencyName: string;
  constituencyNumber: number;
  party: string;
  result: 'won' | 'lost' | 'forfeited_deposit';
  votesReceived: number;
  voteShare: number;
  margin: number;
  rank: number;
  runnerUp: string;
  runnerUpParty: string;
  runnerUpVotes: number;
}

export interface FinancialRecord {
  electionYear: number;
  selfMovableAssets: number;
  selfImmovableAssets: number;
  totalAssets: number;
  totalLiabilities: number;
  netWorth: number;
  selfIncome: number;
  isCrorepati: boolean;
  sourceUrl: string;
}

export interface CriminalRecord {
  hasCriminalCases: boolean;
  totalCases: number;
  seriousCases: number;
  convictions: number;
  ipcSections: string[];
}

export interface PhotoSources {
  myneta?: string;
  myneta_prior?: string;
  prs?: string;
  wikipedia?: string;
  legislature?: string;
}

export interface LegislatorProfile {
  id: string;
  acNo: number;
  name: string;
  displayName: string;
  gender: 'M' | 'F' | 'O';
  age?: number;
  dob?: string;
  dobEstimated?: boolean;
  house: 'state_assembly' | 'lok_sabha' | 'rajya_sabha' | 'state_council';
  stateCode: string;
  stateName: string;
  constituencyName: string;
  constituencyNumber: number;
  district: string;
  reservationType?: 'General' | 'SC' | 'ST' | string;
  currentParty: string;
  currentPartyFull: string;
  isCurrentMember: boolean;
  isCabinetMinister: boolean;
  isChiefMinister: boolean;
  termsServed: number;
  firstElectedYear: number;
  maritalStatus?: 'Single' | 'Married' | 'Widowed' | 'Divorced';
  education: {
    educationLevel: string;
    educationCategory: string;
    selfProfession: string;
    spouseProfession: string;
  };
  photoUrl?: string;
  photoSources: PhotoSources;
  electionHistory: ElectionRecord[];
  financialHistory: FinancialRecord[];
  criminalRecord: CriminalRecord;
  mynetaUrl: string;
  prsUrl?: string;
  wikipediaArticle?: string;
  dataSources: string[];
  lastUpdated: string;
  dataCompleteness: number;
  verificationStatus: 'verified' | 'partial' | 'unverified';
}

