// ── Utility Functions ─────────────────────────────────────────────────

export function getASMLAByConstituency(acNo: number): LegislatorProfile | undefined {
  return AS_MLA_PROFILES.find(p => p.acNo === acNo);
}

export function getASMLAByName(name: string): LegislatorProfile | undefined {
  const q = name.toLowerCase();
  return AS_MLA_PROFILES.find(p =>
    p.name.toLowerCase().includes(q) || p.displayName?.toLowerCase().includes(q)
  );
}

export function getASMLAsByParty(party: string): LegislatorProfile[] {
  return AS_MLA_PROFILES.filter(p => p.currentParty === party);
}

export function getASFemaleMLAs(): LegislatorProfile[] {
  return AS_MLA_PROFILES.filter(p => p.gender === 'F');
}

export function getASCrorepatiMLAs(): LegislatorProfile[] {
  return AS_MLA_PROFILES.filter(p =>
    p.financialHistory.some(f => f.isCrorepati)
  );
}

export function getASMLAsWithCriminalCases(): LegislatorProfile[] {
  return AS_MLA_PROFILES.filter(p => p.criminalRecord.hasCriminalCases);
}

export function getASMultiTermMLAs(): LegislatorProfile[] {
  return AS_MLA_PROFILES.filter(p => p.termsServed >= 2);
}

export function getASPartyStrength(): Record<string, number> {
  const strength: Record<string, number> = {};
  for (const p of AS_MLA_PROFILES) {
    strength[p.currentParty] = (strength[p.currentParty] || 0) + 1;
  }
  return strength;
}

export function getASWealthStats() {
  const sorted = [...AS_MLA_PROFILES]
    .filter(p => p.financialHistory[0]?.totalAssets > 0)
    .sort((a, b) => (b.financialHistory[0]?.totalAssets || 0) - (a.financialHistory[0]?.totalAssets || 0));
  return {
    richest: sorted[0],
    poorest: sorted[sorted.length - 1],
    totalMLAs: sorted.length,
    crorepatis: sorted.filter(p => p.financialHistory[0]?.isCrorepati).length,
    avgNetWorth: sorted.reduce((s, p) => s + (p.financialHistory[0]?.netWorth || 0), 0) / sorted.length,
  };
}

export function getASMLAProfile(acNo: number): LegislatorProfile | undefined {
  return getASMLAByConstituency(acNo);
}
export function getAllASMLAs(): LegislatorProfile[] {
  return AS_MLA_PROFILES;
}
